35	test.describe('US-01-AC-02 field validation (today pinned to 2026-11-20)', () => {
36	  test.beforeEach(async ({ page }) => {
37	    await page.clock.setFixedTime(TODAY);
38	  });
39	
40	  const rows: [string, string | boolean | null, string][] = [
41	    ['Placa', 'AB12', 'Ingresa una placa válida: 3 letras y 3 números (por ejemplo, ABC123).'],
42	    ['Ciudad', null, 'Selecciona tu ciudad.'],
43	    ['Fecha de nacimiento', '01/03/2010', 'Debes ser mayor de edad (18 años o más) para cotizar.'],
44	    ['Modelo (año)', '2005', 'El modelo debe estar entre los últimos 20 años y el próximo año.'],
45	    [CO_CONSENT, false, 'Debes autorizar el tratamiento de tus datos para continuar.'],
46	    ['Nombre completo', 'Al', 'Ingresa tu nombre completo (entre 3 y 80 caracteres).'],
47	  ];
48	
49	  for (const [label, input, message] of rows) {
50	    test(`US-01-AC-02 "${label}" holding ${JSON.stringify(input)} shows its message next to the field and I stay on step 1`, async ({ page }) => {
51	      await page.goto('/co/datos');
52	      await fillColombia(page, { [label]: input });
53	      await continuar(page).click();
54	
55	      await expectDescribedBy(page, label, message);
56	      await expect(field(page, label)).toHaveAttribute('aria-invalid', 'true');
57	      await expect(page).toHaveURL(/\/co\/datos$/);
58	      await expect(continuar(page)).toBeVisible();
59	    });
60	  }
61	});
62	
63	test.describe('US-01-AC-02 / US-01-AC-10 / US-01-AC-18 a required date partly cleared after it was valid (US-01-R3-F01)', () => {
64	  // US-04 spec 11.1: no locale override. The date is typed as dd/mm/aaaa whatever the browser locale, and the
65	  // text box has no segments: the last digit is deleted ("15/05/199") and Tab leaves the date field.
66	  test.beforeEach(async ({ page }) => {
67	    await page.clock.setFixedTime(TODAY);
68	  });
69	
70	  const MESSAGE = 'Ingresa tu fecha de nacimiento.';
71	
72	  /** Press Tab until the focus has left the whole date field (its text box and its "Elegir fecha" button). */
73	  async function tabOutOfDate(page: Page): Promise<void> {
74	    for (let i = 0; i < 4; i++) {
75	      await page.keyboard.press('Tab');
76	      if (await field(page, 'Ciudad').evaluate((el) => el === document.activeElement)) return;
77	    }
78	    throw new Error('the focus did not leave the date field');
79	  }
80	
81	  /** Fill everything, then delete the last digit of the date with the keyboard and Tab away. */
82	  async function clearDateDigit(page: Page): Promise<Locator> {
83	    await page.goto('/co/datos');
84	    await fillColombia(page);
85	    const date = field(page, 'Fecha de nacimiento');
86	    await expect(date).toHaveValue('15/05/1990');
87	    await date.focus();
88	    await page.keyboard.press('End');
89	    await page.keyboard.press('Backspace');
90	    await expect(date).toHaveValue('15/05/199');
91	    await tabOutOfDate(page);
92	    await expectDescribedBy(page, 'Fecha de nacimiento', MESSAGE);
93	    await expect(date).toHaveAttribute('aria-invalid', 'true');
94	    return date;
95	  }
96	
97	  test('US-01-AC-02 / US-01-AC-10 / US-01-AC-18 "Continuar" by click stays on step 1 with the focus on the date, and the stale date is not stored', async ({ page }) => {
98	    const date = await clearDateDigit(page);
99	    await continuar(page).click();
100	
101	    await expect(page).toHaveURL(/\/co\/datos$/);
102	    await expect(date).toBeFocused();
103	    await expectDescribedBy(page, 'Fecha de nacimiento', MESSAGE);
104	    await expect(date).toHaveAttribute('aria-invalid', 'true');
105	    await expect(date).toHaveValue('15/05/199');
106	    const stored = await page.evaluate(() => sessionStorage.getItem('quote-wizard') ?? '');
107	    expect(stored).not.toContain('1990-05-15');
108	    expect(await storedValue(page, 'birthDate')).toBe('');
109	  });
110	
111	  test('US-01-AC-02 / US-01-AC-10 / US-01-AC-18 Enter in another field stays on step 1 with the focus on the date', async ({ page }) => {
112	    const date = await clearDateDigit(page);
113	    await field(page, 'Nombre completo').focus();
114	    await page.keyboard.press('Enter');
115	
116	    await expect(page).toHaveURL(/\/co\/datos$/);
117	    await expect(date).toBeFocused();
118	    await expect(date).toHaveAttribute('aria-invalid', 'true');
119	  });
120	});
121	
122	test.describe('US-01-AC-09 a number the browser cannot parse is invalid and the wizard state holds an empty string', () => {
123	  test.beforeEach(async ({ page }) => {
124	    await page.clock.setFixedTime(TODAY);
125	  });
126	
127	  test('US-01-AC-09 "1e" typed key by key in "Modelo (año)" shows the field message and I stay on step 1', async ({ page }) => {
128	    await page.goto('/co/datos');
129	    await fillColombia(page, { 'Modelo (año)': null });
130	
131	    const year = field(page, 'Modelo (año)');
132	    await year.focus();
133	    await year.pressSequentially('1e');
134	    // The HTML sanitisation rule for <input type="number">: unparseable text reads back as ''.
135	    await expect(year).toHaveValue('');
136	    // `value` reads '' both when "1e" is still on screen and when the text was wiped (US-01-R1-F03),
137	    // so it cannot tell them apart. `validity.badInput` is true only while unparseable text is shown.
138	    await expect.poll(() => year.evaluate((el: HTMLInputElement) => el.validity.badInput)).toBe(true);
139	    // The wizard state and sessionStorage hold '' (AC-09 note, AC-21), not the last parseable text "1"; the typed text stays visible.
140	    await expect
141	      .poll(() => page.evaluate(() => JSON.parse(sessionStorage.getItem('quote-wizard') ?? '{}').step1?.values?.vehicleYear))
142	      .toBe('');
143	
144	    await continuar(page).click();
145	    await expectDescribedBy(page, 'Modelo (año)', 'El modelo debe estar entre los últimos 20 años y el próximo año.');
146	    await expect(year).toHaveAttribute('aria-invalid', 'true');
147	    // Still visible after the failed submit and the focus move.
148	    expect(await year.evaluate((el: HTMLInputElement) => el.validity.badInput)).toBe(true);
149	    await expect(page).toHaveURL(/\/co\/datos$/);
150	  });
151	
152	  test('US-01-AC-09 "abc" cannot even be typed into the number field, and the form still reports the year as missing', async ({ page }) => {
153	    await page.goto('/co/datos');
154	    await fillColombia(page, { 'Modelo (año)': null });
155	    const year = field(page, 'Modelo (año)');
156	    await year.focus();
157	    await year.pressSequentially('abc');
158	    await expect(year).toHaveValue('');
159	    await continuar(page).click();
160	    await expectDescribedBy(page, 'Modelo (año)', 'El modelo debe estar entre los últimos 20 años y el próximo año.');
161	    await expect(page).toHaveURL(/\/co\/datos$/);
162	  });
163	});
164	
165	test.describe('US-01-AC-24 keyboard-only completion (Colombia, desktop)', () => {
166	  // US-04 spec 11.1: the locale override is gone (the date is dd/mm/aaaa whatever the browser locale; us-04 covers en-US).
167	  test.use({ viewport: { width: 1280, height: 800 } });
168	
169	  /** The accessible label text of the element that has focus, or null. */
170	  async function focusedLabel(page: Page): Promise<string | null> {
171	    return page.evaluate(() => {
172	      const el = document.activeElement as (HTMLInputElement | HTMLSelectElement | null);
