4	/**
5	 * Pure validation core (ADR-0004): no Angular, no forms library. "Today" always comes from the
6	 * caller (the injectable clock), never from `new Date()`.
7	 */
8	
9	const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
10	const INTEGER = /^-?\d+$/;
11	
12	export interface YearMonthDay {
13	  year: number;
14	  month: number;
15	  day: number;
16	}
17	
18	/** Strict ISO `YYYY-MM-DD` parse: rejects impossible dates such as 2010-02-30. */
19	export function parseIsoDate(text: string): YearMonthDay | null {
20	  const m = ISO_DATE.exec(text);
21	  if (!m) return null;
22	  const [year, month, day] = [Number(m[1]), Number(m[2]), Number(m[3])];
